import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';
// 🟢 වෙනම තියෙන අලුත් Quiz ෆයිල් එක මෙතනට Import කරගන්නවා
import TeacherQuiz from './TeacherQuiz';

// --- 1. CONTENT MANAGER COMPONENT (File Upload Support) ---
function TeacherContent({ userName, teachingSubject, materials, fetchData }) {
  const [formTitle, setFormTitle] = useState('');
  const [formGrade, setFormGrade] = useState('Grade 9');
  const [formType, setFormType] = useState('PDF');
  const [formFilePath, setFormFilePath] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', formTitle);
    formData.append('material_type', formType);
    formData.append('grade', formGrade);
    formData.append('subject', teachingSubject);
    formData.append('teacher_name', userName);

    if (formType === 'PDF' && selectedFile) {
        formData.append('file', selectedFile); 
    } else {
        formData.append('file_path', formFilePath);
    }

    axiosInstance.post('http://localhost:8081/api/add-material', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
    }).then(res => {
      if (res.data.status === "Success") {
        alert("✅ Lesson Material Published!");
        fetchData(); setFormTitle(''); setFormFilePath(''); setSelectedFile(null);
      }
    });
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s' }}>
      <h2>📤 Content Manager ({teachingSubject})</h2>
      <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <input type="text" placeholder="Lesson Title" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={styles.fullInput} />
          <div style={{ display: 'flex', gap: '20px' }}>
            <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={styles.fullInput}><option>Grade 9</option><option>Grade 10</option><option>Grade 11</option></select>
            <select value={formType} onChange={e => setFormType(e.target.value)} style={styles.fullInput}><option value="PDF">PDF Handout</option><option value="Video">Video Lesson</option></select>
          </div>
          {formType === 'PDF' ? (
            <input type="file" accept=".pdf" onChange={e => setSelectedFile(e.target.files[0])} required style={styles.fullInput} />
          ) : (
            <input type="text" placeholder="YouTube Video URL" value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={styles.fullInput} />
          )}
          <button type="submit" style={styles.publishBtn}>Publish Material Target</button>
        </form>
      </div>
    </div>
  );
}

// --- 2. MAIN PORTAL WITH VALIDATIONS & REPORT VIEWS ---
export default function TeacherDashboard({ userName, userUsername, subject, qualifications, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [materials, setMaterials] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [isEditing, setIsEditing] = useState(false);

  const fullSubject = subject || 'Grade 9 - IT'; 
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 9';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [profileData, setProfileData] = useState({ name: userName, username: userUsername, qualifications, email, phone, address });

  const fetchData = () => {
    axiosInstance.get('http://localhost:8081/api/learning-materials').then(res => setMaterials(res.data));
    axiosInstance.get('http://localhost:8081/api/timetable').then(res => setTimetable(res.data.filter(c => c.teacher === userName)));
  };

  useEffect(() => { fetchData(); }, [userName]);

  // 🟢 FORM VALIDATION LOGIC
  const handleProfileUpdate = () => {
    const phoneRegex = /^[0-9]{10}$/;
    if (!phoneRegex.test(profileData.phone)) {
        alert("❌ Error: Contact Number must be exactly 10 numeric digits!");
        return;
    }

    if (profileData.email && !profileData.email.includes('@')) {
        alert("❌ Error: Invalid Email Address! Must contain '@' symbol.");
        return;
    }

    alert("✅ Validation Passed! Profile details updated successfully.");
    setIsEditing(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div>
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px' }}>
              <h1>Welcome back, {profileData.name}! 👋</h1>
              <p>System operational for target: <strong>Grade 9 IT</strong> and other mapped classes.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" textColor="#3b82f6" />
              <DashboardCard title="Assigned Grade" count={teachingGrade} icon="🏫" textColor="#7c3aed" />
              <DashboardCard title="Total Handouts" count={materials.length} icon="📂" textColor="#eab308" />
            </div>
            
            <h3>🏫 Active Scheduled Timetable Mapping</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px', marginTop: '15px' }}>
                {timetable.map(c => (
                  <div key={c.id} style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderTop: '5px solid #15803d' }}>
                    <div style={{ fontWeight: 'bold' }}>{c.grade} - {c.subject}</div>
                    <div style={{ fontSize: '13px', color: '#64748b' }}>🕒 {c.day} ({c.time_slot})</div>
                  </div>
                ))}
            </div>
          </div>
        );

      case 'upload': 
        return <TeacherContent userName={userName} teachingSubject={teachingSubject} materials={materials} fetchData={fetchData} />;
      
      case 'quiz': 
        // 🟢 වෙනම තියෙන අලුත් TeacherQuiz ෆයිල් එකට Props යැවීම මෙතනින් සිදුවේ
        return <TeacherQuiz userName={userName} subject={fullSubject} qualifications={qualifications} />;
      
      case 'activities':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>🧩 Manage Interactive Learning Exercises</h2>
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
              <p style={{ color: '#64748b', marginBottom: '20px' }}>Create alternative interactive games for students to practice terms after lessons.</p>
              <div style={{ display: 'flex', gap: '25px' }}>
                <div style={{ flex: 1, padding: '20px', border: '1px dashed #cbd5e1', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>🧩 Word Matching Grid</h3>
                  <button onClick={() => alert("Setting up Vocabulary Matching Grid...")} style={styles.submitBtn}>Configure Game</button>
                </div>
                <div style={{ flex: 1, padding: '20px', border: '1px dashed #cbd5e1', borderRadius: '10px', textAlign: 'center' }}>
                  <h3>💡 True / False Flashcards</h3>
                  <button onClick={() => alert("Setting up Revision Flashcards...")} style={styles.submitBtn}>Configure Deck</button>
                </div>
              </div>
            </div>
          </div>
        );

      case 'reports':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>📈 Student Performance Analytics Report</h2>
            <div style={styles.tableBox}>
              <div style={{display:'flex', justifyContent:'space-between', marginBottom:'15px'}}>
                <span style={{fontWeight:'bold', color:'#475569'}}>Grade 9 IT Exam Summary Logs</span>
                <button onClick={() => alert("📥 Exporting analytical performance chart report as PDF/Excel...")} style={{padding:'6px 15px', backgroundColor:'#1e293b', color:'white', border:'none', borderRadius:'6px', cursor:'pointer', fontWeight:'bold', fontSize:'12px'}}>Download Full Report</button>
              </div>
              <table style={styles.table}>
                <thead>
                  <tr style={styles.thRow}><th>Student Name</th><th>Quiz Paper Type</th><th>Marks Scored</th><th>Grade Status</th></tr>
                </thead>
                <tbody>
                  <tr style={styles.tdRow}><td>Kasun Perera</td><td>[Lesson Quiz] Introduction to IT</td><td>18 / 20</td><td><span style={{color:'#16a34a', fontWeight:'bold'}}>Excellent</span></td></tr>
                  <tr style={styles.tdRow}><td>Nimal Silva</td><td>[Term Exam] 1st Term Evaluation</td><td>78 / 100</td><td><span style={{color:'#16a34a', fontWeight:'bold'}}>Pass (A)</span></td></tr>
                  <tr style={styles.tdRow}><td>Ruwan Fernando</td><td>[Lesson Quiz] Hardware Component Revision</td><td>12 / 20</td><td><span style={{color:'#eab308', fontWeight:'bold'}}>Average</span></td></tr>
                </tbody>
              </table>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2>👤 My Profile Settings & Validation Auditing</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', maxWidth: '500px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
                  <h3>Profile Records</h3>
                  {!isEditing ? <button onClick={() => setIsEditing(true)} style={styles.editProfileBtn}>✏️ Edit Profile</button> : <button onClick={handleProfileUpdate} style={styles.saveProfileBtn}>💾 Save Changes</button>}
                </div>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                  <div><label style={styles.label}>Full Name</label><input type="text" value={profileData.name} onChange={e => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>Audited Email Address</label><input type="text" value={profileData.email} onChange={e => setProfileData({...profileData, email: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                  <div><label style={styles.label}>Validated Phone Number</label><input type="text" value={profileData.phone} onChange={e => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={styles.inputStyleProfile(isEditing)} /></div>
                </div>
            </div>
          </div>
        );
      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER DASHBOARD</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px', overflowY: 'auto' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard Overview" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'quiz'} onClick={() => setActiveTab('quiz')} icon="📝" text="Quiz & Exam Manager" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🧩" text="Manage Activities" />
          <SidebarBtn active={activeTab === 'reports'} onClick={() => setActiveTab('reports')} icon="📈" text="View Reports" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile Settings" />
        </div>
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}><button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button></div>
      </div>
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>{renderContent()}</div>
    </div>
  );
}

// --- CORE INTERFACE REUSABLE STYLES ---
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${textColor}`, boxShadow: '0 4px 15px rgba(0,0,0,0.02)' }}>
    <div><p style={{ margin: 0, color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p><h2>{count}</h2></div>
    <div style={{ fontSize: '28px' }}>{icon}</div>
  </div>
);

const styles = {
  label: { display: 'block', marginBottom: '6px', color: '#475569', fontSize: '13px', fontWeight: 'bold' },
  inlineInput: { flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none' },
  submitBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '13px' },
  fullInput: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', fontSize: '14px' },
  publishBtn: { padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', width: '100%', marginTop: '10px' },
  tableBox: { backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' },
  table: { width: '100%', borderCollapse: 'collapse', textAlign: 'left' },
  thRow: { borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px', height: '40px' },
  tdRow: { borderBottom: '1px solid #f1f5f9', fontSize: '14px', height: '45px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '8px', width: '100%' },
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  editProfileBtn: { padding: '6px 14px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  saveProfileBtn: { padding: '6px 14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  inputStyleProfile: (isEditing) => ({ width: '100%', padding: '12px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px' })
};
